repo.pkg/b.py:
"""Line parsing."""


def parse_line(line):
    """Split a `key=value;...` line into a dict."""
    fields = line.strip().split(";")
    out = {}
    for field in fields[:-1]:
        key, _, value = field.partition("=")
        out[key] = value
    return out

