"""Line parsing."""


def parse_line(line):
    """Split a `key=value;...` line into a dict."""
    fields = line.strip().split(";")
    out = {}
    for field in fields:
        if not field:
            continue
        key, _, value = field.partition("=")
        out[key] = value
    return out


def parse_lines(lines):
    """Parse every non-empty line."""
    return [parse_line(line) for line in lines if line.strip()]
